  'tour.step.welcome.title': 'Bienvenue dans Foreman',
  'tour.step.welcome.body': 'Lancez des agents de code en parallèle, chacun sur sa propre branche dans sa propre copie de votre dépôt. Tout reste sur cet ordinateur. Voici où se trouvent les choses.',
  'tour.step.addRepo.title': 'Ajouter un dépôt',
  'tour.step.addRepo.body': 'Ouvrez un dossier qui est déjà un dépôt git, clonez-en un depuis GitHub ou utilisez Démarrage rapide pour en créer un. Faites un clic droit sur un dépôt pour ses réglages : script d’installation, script d’exécution et vérifications.',
  'tour.step.addRepo.where': 'le bouton + dans la bande des icônes de dépôts',
  'tour.step.newWorkspace.title': 'Démarrer un espace de travail',
  'tour.step.newWorkspace.body': 'Chaque espace de travail est une nouvelle branche dans son propre worktree, avec ses propres ports et son terminal : les agents ne se gênent jamais. Appuyez sur {key}, puis décrivez la tâche ; les images fonctionnent aussi.',
  'tour.step.newWorkspace.where': 'le bouton Nouvel espace de travail, près du haut',
  'tour.step.needsYou.title': 'À vous',
  'tour.step.needsYou.body': 'Avec plusieurs agents en cours, vous ne les surveillez plus. Tout ce qui attend votre réponse (une approbation, une question, un plan, un tour en échec) est réuni ici et sur l’Accueil, avec un compteur, une notification et un badge dans la zone de notification ou la barre des menus. {next} saute au prochain espace de travail qui vous attend ; {jump} à ce qui vous attend dans la conversation en cours.',
  'tour.step.needsYou.where': 'les filtres Tous, À vous, En cours et Épinglés',
  'tour.step.layout.title': 'Deux façons de voir votre travail',
  'tour.step.layout.body': 'Trois volets affiche un espace de travail avec ses changements et son terminal à côté ; c’est ce que vous avez maintenant. Vignettes affiche les conversations de plusieurs espaces de travail côte à côte. Changez à tout moment avec {palette} (« Passer aux vignettes ») ou dans Réglages → Apparence → Disposition de la fenêtre.',
  'tour.step.automations.title': 'Modèles et Automatisations',
  'tour.step.automations.body': 'Les modèles sont des prompts avec des blancs pour les détails ; gardez les vôtres, ou ceux du dépôt. Les automatisations lancent un modèle selon une planification (tous les jours, toutes les semaines, etc.) tant que Foreman est ouvert, avec un calendrier de ce qui a tourné et de la suite.',
  'tour.step.automations.where': 'Automatisations, en haut de la barre latérale',
  'tour.step.assistant.title': 'Demander à l’assistant',
  'tour.step.assistant.body': 'Vous ne savez pas où trouver quelque chose ? Demandez ici ({key}). Il vous mène au réglage exact et ne change jamais rien. Il fonctionne avec Claude : connectez-vous d’abord à Claude.',
  'tour.step.assistant.where': 'Assistant, sous Automatisations',
  'tour.step.settings.title': 'Réglages',
  'tour.step.settings.body': 'Accessibilité : taille du texte, zoom, modes de couleur et annonces pour lecteurs d’écran. Agents : connectez-vous et choisissez votre agent par défaut. MCP : les serveurs du dépôt s’approuvent dans le panneau Git d’un espace de travail, et les agents reçoivent les outils propres à Foreman. Les espaces de travail distants (expérimentaux, désactivés par défaut) exécutent un espace de travail dans un bac à sable cloud.',
  'tour.step.settings.where': 'l’engrenage dans la bande des icônes de dépôts',
  'tour.step.help.title': 'Revenir ici',
  'tour.step.help.body': 'Relancez cette visite d’ici. Tout le reste est à portée de recherche : {palette} ouvre la palette de commandes et {shortcuts} liste tous les raccourcis.',
